import { path } from '@servicenow/sdk-build-core'
import { createTestContext, findInput, getMergedRecordUpdates, loadTestFile, unzipInputArray } from '../test-utils'

/**
 * Example Unit Tests - Part 4
 *
 * This test suite covers 3 example files with comprehensive bidirectional testing:
 * 1. credit-card-approval-flow.now.ts - Flow with approval logic
 * 2. email-incident-creation-flow.now.ts - Flow with email trigger
 * 3. network-incident-escalation-flow.now.ts - Flow with escalation logic
 *
 * Each file has:
 * - Fluent → XML tests: Verify correct XML generation from TypeScript
 * - XML → Fluent tests: Verify correct TypeScript generation from XML
 *
 * All tests use fixed patterns with no conditional logic.
 */

describe('Example Unit Tests - Part 4', () => {
    const ctx = createTestContext({ rootDir: path.resolve(__dirname, '../project') })
    beforeAll(() => ctx.initialize())
    afterEach(() => ctx.cleanup())
    // ============================================================================
    // TEST FILE 1: credit-card-approval-flow.now.ts
    // ============================================================================
    describe('File 1: credit-card-approval-flow - Fluent to XML', () => {
        test('Flow with credit card approval logic and trigger validation', async () => {
            const merged = await getMergedRecordUpdates(
                ctx.createProject(),
                'credit-card-approval-flow.now.ts',
                'example-unit-tests/fluent'
            )

            // Verify flow record
            expect(merged['sys_hub_flow']).toBeDefined()
            const flows = merged['sys_hub_flow']
            expect(flows.length).toBeGreaterThanOrEqual(1)

            const flow = flows[0]
            expect(flow).toBeDefined()
            expect(flow.type).toBe('flow')
            expect(flow.run_as).toBeDefined()

            // Verify and validate trigger
            expect(merged['sys_hub_trigger_instance_v2']).toBeDefined()
            const triggerInstances = merged['sys_hub_trigger_instance_v2']
            expect(triggerInstances.length).toBeGreaterThan(0)

            const trigger = triggerInstances[0]
            expect(trigger.trigger_type).toBeDefined()
            expect(trigger.trigger_inputs).toBeDefined()

            // Validate trigger inputs
            const triggerInputs = unzipInputArray(trigger.trigger_inputs)
            const val = (name: string) => findInput(triggerInputs, name)?.value

            expect(val('table')).toBe('sc_req_item')
            expect(val('condition')).toContain('cat_item.name')
            expect(val('run_flow_in')).toBe('background')
        })

        test('Action instances with lookUpRecord and askForApproval validations', async () => {
            const merged = await getMergedRecordUpdates(
                ctx.createProject(),
                'credit-card-approval-flow.now.ts',
                'example-unit-tests/fluent'
            )

            // Verify action instances
            expect(merged['sys_hub_action_instance_v2']).toBeDefined()
            const actionInstances = merged['sys_hub_action_instance_v2']
            expect(actionInstances.length).toBeGreaterThan(0)

            // Find and validate lookUpRecord action for requester with datapills
            const lookupRequesterAction = actionInstances.find(
                (action: any) => action.comment === 'Retrieve requester details'
            )
            expect(lookupRequesterAction).toBeDefined()

            const lookupRequesterInputsArr = unzipInputArray(lookupRequesterAction.values)
            const lookupRequesterInputs = (name: string) => findInput(lookupRequesterInputsArr, name)?.value

            expect(lookupRequesterInputs('table')).toBe('sys_user')
            // Verify conditions contain datapill: {{uuid.requested_for}}
            const requesterConditions = lookupRequesterInputs('conditions')
            expect(requesterConditions).toContain('sys_id=')
            expect(requesterConditions).toMatch(/\{\{[^}]+\.requested_for\}\}/)
            expect(requesterConditions).toContain('requested_for')

            // Find and validate lookUpRecord action for direct manager
            const lookupManagerAction = actionInstances.find(
                (action: any) => action.comment === 'Retrieve direct manager details'
            )
            expect(lookupManagerAction).toBeDefined()

            const managerInputsArr = unzipInputArray(lookupManagerAction.values)
            const managerInputs = (name: string) => findInput(managerInputsArr, name)?.value

            expect(managerInputs('table')).toBe('sys_user')
            expect(managerInputs('conditions')).toContain('sys_id=')

            // Find and validate askForApproval action
            const approvalAction = actionInstances.find(
                (action: any) => action.comment === 'Request approval from direct manager'
            )
            expect(approvalAction).toBeDefined()

            const approvalInputsArr = unzipInputArray(approvalAction.values)
            const approvalInputs = (name: string) => findInput(approvalInputsArr, name)?.value

            expect(approvalInputs('table')).toBe('sc_req_item')
            expect(approvalInputs('approval_reason')).toContain('Please review and approve')
            expect(approvalInputs('approval_field')).toBe('approval')
            expect(approvalInputs('approval_conditions')).toBeDefined()
        })
    })

    describe('File 1: credit-card-approval-flow - XML to Fluent', () => {
        test('Flow with approval logic transforms correctly from XML', async () => {
            const project = ctx.createProject()

            const xmlContent = loadTestFile(
                'sys_hub_flow_a9f76b48fd434854bd054e6d73302619.xml',
                'example-unit-tests/xml'
            )
            const { changedFiles } = await project.transform({
                path: 'sys_hub_flow_a9f76b48fd434854bd054e6d73302619.xml',
                content: xmlContent,
            })

            expect(changedFiles).toHaveLength(1)
            const content = changedFiles[0].getContent()

            // Verify imports
            expect(content).toContain('import {')
            expect(content).toContain('Flow')
            expect(content).toContain('trigger')
            expect(content).toContain('action')

            // Verify flow definition
            expect(content).toContain('Flow(')
            expect(content).toContain("name: 'Corporate Credit Card Approval Flow'")

            // Verify trigger
            expect(content).toContain('trigger.')
            expect(content).toContain('wfa.trigger(')

            // Verify actions
            expect(content).toContain('wfa.action(')
            expect(content).toContain('action.')

            // Verify annotations
            expect(content).toContain('annotation:')
        })
    })

    // ============================================================================
    // TEST FILE 2: email-incident-creation-flow.now.ts
    // ============================================================================
    describe('File 2: email-triggered-incident-task-flow - Fluent to XML', () => {
        test('Flow with email trigger validation', async () => {
            const merged = await getMergedRecordUpdates(
                ctx.createProject(),
                'email-triggered-incident-task-flow.now.ts',
                'example-unit-tests/fluent'
            )

            // Verify flow record
            expect(merged['sys_hub_flow']).toBeDefined()
            const flows = merged['sys_hub_flow']
            expect(flows.length).toBeGreaterThanOrEqual(1)

            const flow = flows.find((f: any) => f.name === 'Email-Triggered Incident and Task Creation Flow')
            expect(flow).toBeDefined()
            expect(flow.type).toBe('flow')
            expect(flow.run_as).toBeDefined()

            // Verify and validate trigger
            expect(merged['sys_hub_trigger_instance_v2']).toBeDefined()
            const triggerInstances = merged['sys_hub_trigger_instance_v2']
            expect(triggerInstances.length).toBeGreaterThan(0)

            const trigger = triggerInstances[0]
            expect(trigger.trigger_type).toBeDefined()
            expect(trigger.trigger_inputs).toBeDefined()

            // Validate inbound email trigger inputs
            const triggerInputs = unzipInputArray(trigger.trigger_inputs)
            const val = (name: string) => findInput(triggerInputs, name)?.value

            expect(val('email_conditions')).toBe('subjectLIKEraise incident or task')
            expect(val('target_table')).toBe('incident')
            expect(val('order')).toBe(100)
        })

        test('Action instances with log validation', async () => {
            const merged = await getMergedRecordUpdates(
                ctx.createProject(),
                'email-triggered-incident-task-flow.now.ts',
                'example-unit-tests/fluent'
            )

            // Verify flow logic instances for nested if-else conditions
            expect(merged['sys_hub_flow_logic_instance_v2']).toBeDefined()
            const flowLogicInstances = merged['sys_hub_flow_logic_instance_v2']
            expect(flowLogicInstances.length).toBeGreaterThan(0)

            // Verify if condition for internal sender
            const ifInternalSender = flowLogicInstances.find(
                (fl: any) => fl.comment === 'Check if sender is from ServiceNow (internal)'
            )
            expect(ifInternalSender).toBeDefined()

            // Verify nested if condition for P1 priority
            const ifP1Priority = flowLogicInstances.find(
                (fl: any) => fl.comment === 'Check if email subject contains P1'
            )
            expect(ifP1Priority).toBeDefined()

            // Verify else conditions
            const elseInternalNonP1 = flowLogicInstances.find(
                (fl: any) => fl.comment === 'Handle internal sender without P1 priority'
            )
            expect(elseInternalNonP1).toBeDefined()

            const elseExternalSender = flowLogicInstances.find(
                (fl: any) => fl.comment === 'Handle external sender (non-ServiceNow)'
            )
            expect(elseExternalSender).toBeDefined()

            // Verify action instances
            expect(merged['sys_hub_action_instance_v2']).toBeDefined()
            const actionInstances = merged['sys_hub_action_instance_v2']
            expect(actionInstances.length).toBeGreaterThan(0)

            // Find and validate the log action for email receipt
            const logEmailAction = actionInstances.find((action: any) => action.comment === 'Log email receipt')
            expect(logEmailAction).toBeDefined()

            const logInputsArr = unzipInputArray(logEmailAction.values)
            const logInputs = (name: string) => findInput(logInputsArr, name)?.value

            expect(logInputs('log_level')).toBe('info')
            expect(logInputs('log_message')).toContain('Email received from:')

            // Validate lookUpRecord actions for sender and manager
            const lookupSenderAction = actionInstances.find(
                (action: any) => action.comment === 'Retrieve sender user record'
            )
            expect(lookupSenderAction).toBeDefined()

            const lookupManagerAction = actionInstances.find(
                (action: any) => action.comment === 'Retrieve sender manager record'
            )
            expect(lookupManagerAction).toBeDefined()

            // Validate createRecord actions for P1 tasks
            const createManagerTaskAction = actionInstances.find(
                (action: any) => action.comment === 'Create P1 task for sender manager with body as short description'
            )
            expect(createManagerTaskAction).toBeDefined()

            const createSenderTaskAction = actionInstances.find(
                (action: any) => action.comment === 'Create P1 task for sender with subject as short description'
            )
            expect(createSenderTaskAction).toBeDefined()

            // Validate createRecord actions for P3 incidents
            const createP3InternalAction = actionInstances.find(
                (action: any) => action.comment === 'Create P3 incident for internal sender'
            )
            expect(createP3InternalAction).toBeDefined()

            const createP3ExternalAction = actionInstances.find(
                (action: any) => action.comment === 'Create P3 incident for external sender'
            )
            expect(createP3ExternalAction).toBeDefined()

            // Validate sendNotification actions
            const sendP1NotificationAction = actionInstances.find(
                (action: any) => action.comment === 'Send P1 task creation confirmation'
            )
            expect(sendP1NotificationAction).toBeDefined()

            const sendP3InternalNotificationAction = actionInstances.find(
                (action: any) => action.comment === 'Send P3 incident creation confirmation'
            )
            expect(sendP3InternalNotificationAction).toBeDefined()

            const sendP3ExternalNotificationAction = actionInstances.find(
                (action: any) => action.comment === 'Send P3 incident creation confirmation'
            )
            expect(sendP3ExternalNotificationAction).toBeDefined()

            // Validate associateRecordToEmail actions
            const associateP3InternalAction = actionInstances.find(
                (action: any) => action.comment === 'Associate email to P3 incident'
            )
            expect(associateP3InternalAction).toBeDefined()

            // Validate log actions for different scenarios
            const logP1ProcessingAction = actionInstances.find(
                (action: any) => action.comment === 'Log P1 internal email processing'
            )
            expect(logP1ProcessingAction).toBeDefined()

            const logP1TasksCreatedAction = actionInstances.find(
                (action: any) => action.comment === 'Log successful P1 task creation'
            )
            expect(logP1TasksCreatedAction).toBeDefined()

            const logFlowCompletionAction = actionInstances.find(
                (action: any) => action.comment === 'Log flow completion'
            )
            expect(logFlowCompletionAction).toBeDefined()
        })
    })

    describe('File 2: email-incident-creation-flow - XML to Fluent', () => {
        test('Flow with email trigger transforms correctly from XML', async () => {
            const project = ctx.createProject()

            const xmlContent = loadTestFile(
                'sys_hub_flow_5b290ecb9b3446deb74c59557ae3d27c.xml',
                'example-unit-tests/xml'
            )
            const { changedFiles } = await project.transform({
                path: 'sys_hub_flow_5b290ecb9b3446deb74c59557ae3d27c.xml',
                content: xmlContent,
            })

            expect(changedFiles).toHaveLength(1)
            const content = changedFiles[0].getContent()

            // Verify imports
            expect(content).toContain('import {')
            expect(content).toContain('Flow')
            expect(content).toContain('trigger')
            expect(content).toContain('action')

            // Verify flow definition
            expect(content).toContain('Flow(')
            expect(content).toContain("name: 'Email-Triggered Incident and Task Creation Flow'")

            // Verify trigger
            expect(content).toContain('trigger.')
            expect(content).toContain('wfa.trigger(')

            // Verify actions
            expect(content).toContain('wfa.action(')
            expect(content).toContain('action.')

            // Verify annotations
            expect(content).toContain('annotation:')
        })
    })

    // ============================================================================
    // TEST FILE 3: network-incident-escalation-flow.now.ts
    // ============================================================================
    describe('File 3: network-incident-escalation-flow - Fluent to XML', () => {
        test('Flow with escalation logic', async () => {
            const merged = await getMergedRecordUpdates(
                ctx.createProject(),
                'network-incident-escalation-flow.now.ts',
                'example-unit-tests/fluent'
            )

            // Verify flow record
            expect(merged['sys_hub_flow']).toBeDefined()
            const flows = merged['sys_hub_flow']
            expect(flows.length).toBeGreaterThanOrEqual(1)

            const flow = flows.find((f: any) => f.name === 'Network Incident Escalation Flow')
            expect(flow).toBeDefined()
            expect(flow.type).toBe('flow')
            expect(flow.run_as).toBeDefined()
        })

        test('Flow logic and action instances for escalation are properly created', async () => {
            const merged = await getMergedRecordUpdates(
                ctx.createProject(),
                'network-incident-escalation-flow.now.ts',
                'example-unit-tests/fluent'
            )

            // Verify flow logic instances
            expect(merged['sys_hub_flow_logic_instance_v2']).toBeDefined()
            const flowLogicInstances = merged['sys_hub_flow_logic_instance_v2']
            expect(flowLogicInstances.length).toBeGreaterThan(0)

            // Verify first instance has proper structure
            const firstInstance = flowLogicInstances[0]
            expect(firstInstance.logic_definition).toBeDefined()
            expect(firstInstance.values).toBeDefined()

            // Verify action instances
            expect(merged['sys_hub_action_instance_v2']).toBeDefined()
            const actionInstances = merged['sys_hub_action_instance_v2']
            expect(actionInstances.length).toBeGreaterThan(0)

            // Verify action structure
            const firstAction = actionInstances[0]
            expect(firstAction.action_type).toBeDefined()
            expect(firstAction.values).toBeDefined()
        })
    })

    describe('File 3: network-incident-escalation-flow - XML to Fluent', () => {
        test('Flow with escalation logic transforms correctly from XML', async () => {
            const project = ctx.createProject()

            const xmlContent = loadTestFile(
                'sys_hub_flow_afc37ff7e9a94e14b9fd5c606b9bfd49.xml',
                'example-unit-tests/xml'
            )
            const { changedFiles } = await project.transform({
                path: 'sys_hub_flow_afc37ff7e9a94e14b9fd5c606b9bfd49.xml',
                content: xmlContent,
            })

            expect(changedFiles).toHaveLength(1)
            const content = changedFiles[0].getContent()

            // Verify imports
            expect(content).toContain('import {')
            expect(content).toContain('Flow')
            expect(content).toContain('trigger')
            expect(content).toContain('action')

            // Verify flow definition
            expect(content).toContain('Flow(')
            expect(content).toContain("name: 'Network Incident Escalation Flow'")

            // Verify trigger
            expect(content).toContain('trigger.')
            expect(content).toContain('wfa.trigger(')

            // Verify actions
            expect(content).toContain('wfa.action(')
            expect(content).toContain('action.')

            // Verify annotations
            expect(content).toContain('annotation:')
        })
    })
})
